INSERT INTO `tour_line` (`title`, `cover_image`, `images`, `destination`, `departure_city`, `price`, `days`, `description`, `schedule`, `includes`, `excludes`, `stock`, `sales`, `rating`, `review_count`, `category`, `tags`) VALUES
('云南大理丽江双飞6日游', 'https://picsum.photos/800/400?random=1', '["https://picsum.photos/800/400?random=11","https://picsum.photos/800/400?random=12","https://picsum.photos/800/400?random=13"]', '云南', '上海', 2999.00, 6, '感受彩云之南的魅力，游览大理古城、洱海、丽江古城、玉龙雪山等著名景点。', '[{"title":"上海-昆明","content":"乘机前往春城昆明，接机后入住酒店休息。"},{"title":"昆明-大理","content":"乘车前往大理，游览洱海、崇圣寺三塔。"},{"title":"大理古城","content":"游览大理古城，体验白族文化。"},{"title":"大理-丽江","content":"前往丽江，游览束河古镇。"},{"title":"玉龙雪山","content":"游览玉龙雪山，蓝月谷。"},{"title":"丽江-上海","content":"自由活动后乘机返回上海。"}]', '["往返机票","5晚酒店住宿","行程内用餐","景点首道门票","旅游大巴","导游服务"]', '["个人消费","单房差","自费项目","旅游意外险"]', 50, 356, 4.8, 128, '假期游', '古城,摄影,自然'),
INSERT INTO `review` (`user_id`, `line_id`, `rating`, `content`) VALUES
(1, 1, 5, '非常棒的旅行体验！导游很专业，行程安排合理，风景太美了！'),
(2, 1, 4, '整体不错，就是行程有点赶，建议多留点自由活动时间。'),
(3, 1, 5, '云南真的太美了，下次还要来！'),
(1, 2, 5, '三亚的海水太清澈了，蜈支洲岛超级美！'),
(2, 2, 5, '酒店很棒，服务也很好，强烈推荐！'),
(1, 6, 4, '故宫很震撼，长城也很壮观，就是人太多了。'),
(3, 6, 5, '北京不愧是古都，历史文化底蕴深厚。');
